
import 'b1_course_data.dart';

/// C2 specialist continuation: lessons 571-600.
class C2StrategicCourseData {
  static List<String> _rotate(List<String> values, int answer) =>
      List<String>.generate(values.length,
          (i) => values[(i - answer + values.length) % values.length]);

  static B1Question _question(String prompt, List<String> options,
          int answer, String explanation) =>
      B1Question(prompt, _rotate(options, answer), answer, explanation);

  static B1Lesson _build(_Spec s) {
