  static final List<B1Lesson> lessons = [
    _Spec(unitId: "c2-u16", number: 571, title: "التحضير للتفاوض متعدد الأطراف", term: "müzakere hazırlığı", goal: "حدد الأطراف ومصالحها وصلاحياتها والمعلومات المتاحة والنتيجة المقبولة قبل بدء التفاوض.", rule: "حدد الأطراف ومصالحها وصلاحياتها والمعلومات المتاحة والنتيجة المقبولة قبل بدء التفاوض.", meaning: "التحضير للتفاوض", sentence: "Müzakereden önce tarafların önceliklerini ve yetki sınırlarını belirledik.", translation: "حددنا أولويات الأطراف وحدود صلاحياتها قبل التفاوض.", form: "paydaş haritası", functionText: "إعداد خريطة أصحاب المصلحة", task: "أنشئ ملف تحضير يوضح الأطراف والمصالح والبدائل وحدود التفويض.", example: "Hazırlık dosyası belirsizliği azaltır ve görüşmeleri verimli kılar. | يقلل ملف التحضير الغموض ويجعل المباحثات أكثر كفاءة.", dialogue: "A: İlk adım ne olmalı? — ما الخطوة الأولى؟\\nB: Tarafları ve temel çıkarlarını haritalandırmalıyız. — ينبغي رسم خريطة للأطراف ومصالحها الأساسية."),
    _Spec(unitId: "c2-u16", number: 572, title: "صياغة جدول أعمال تفاوضي", term: "müzakere gündemi", goal: "رتب القضايا بحسب الأولوية والاعتماد المتبادل، وافصل المسائل الإجرائية عن الموضوعية.", rule: "رتب القضايا بحسب الأولوية والاعتماد المتبادل، وافصل المسائل الإجرائية عن الموضوعية.", meaning: "جدول أعمال التفاوض", sentence: "Gündemi ortak önceliklere göre yeniden düzenledik.", translation: "أعدنا ترتيب جدول الأعمال وفق الأولويات المشتركة.", form: "öncelik sıralaması", functionText: "ترتيب الأولويات", task: "صمم جدول أعمال يحدد البنود والوقت والمسؤول عن كل بند.", example: "Gündem, tartışmanın kapsamını ve sırasını netleştirir. | يوضح جدول الأعمال نطاق النقاش وترتيبه.", dialogue: "A: Önce hangi konuyu ele alalım? — أي موضوع نتناول أولاً؟\\nB: Diğer kararları etkileyen konudan başlamalıyız. — ينبغي أن نبدأ بالموضوع الذي يؤثر في القرارات الأخرى."),
    _Spec(unitId: "c2-u16", number: 573, title: "التمييز بين المواقف والمصالح", term: "temel çıkar", goal: "لا تتوقف عند الطلب المعلن؛ استكشف الحاجة أو المصلحة التي تفسر الموقف وابحث عن بدائل تلبيها.", rule: "لا تتوقف عند الطلب المعلن؛ استكشف الحاجة أو المصلحة التي تفسر الموقف وابحث عن بدائل تلبيها.", meaning: "المصلحة الأساسية", sentence: "Görünürdeki talebin arkasındaki temel çıkarı anlamaya çalıştık.", translation: "حاولنا فهم المصلحة الأساسية وراء الطلب الظاهر.", form: "ihtiyaç analizi", functionText: "تحليل الاحتياجات", task: "حلل موقفين تفاوضيين واستخرج المصالح التي يمكن أن تكون مشتركة.", example: "Pozisyonlar çatışsa bile çıkarlar kısmen örtüşebilir. | حتى إن تعارضت المواقف فقد تتداخل المصالح جزئياً.", dialogue: "A: Karşı taraf yalnızca bu seçeneği istiyor. — الطرف الآخر يريد هذا الخيار وحده.\\nB: Hangi ihtiyacı karşıladığını soralım. — لنسأل عن الحاجة التي يلبيها."),
    _Spec(unitId: "c2-u16", number: 574, title: "تقديم مقترحات مشروطة", term: "koşullu teklif", goal: "اربط العرض بشرط واضح وقابل للتحقق، وبيّن المقابل المتوقع دون غموض أو تهديد.", rule: "اربط العرض بشرط واضح وقابل للتحقق، وبيّن المقابل المتوقع دون غموض أو تهديد.", meaning: "عرض مشروط", sentence: "Bu süreyi kabul edebiliriz; karşılığında raporlama sıklığı artırılmalıdır.", translation: "يمكننا قبول هذه المدة؛ على أن تزداد وتيرة التقارير في المقابل.", form: "karşılıklı koşul", functionText: "شرط متبادل", task: "اكتب ثلاثة عروض مشروطة وحدد شرط كل عرض ومقابله.", example: "Koşul ve karşılık aynı açıklıkta ifade edilmelidir. | يجب التعبير عن الشرط والمقابل بالوضوح نفسه.", dialogue: "A: Teslim tarihini uzatabilir misiniz? — هل يمكنكم تمديد موعد التسليم؟\\nB: Evet, ancak ara raporlar haftalık sunulursa. — نعم، إذا قُدمت تقارير مرحلية أسبوعية."),
    _Spec(unitId: "c2-u16", number: 575, title: "معالجة الجمود التفاوضي", term: "müzakere tıkanıklığı", goal: "عند الجمود، أعد تعريف المشكلة أو جزّئها أو اطلب معياراً محايداً بدلاً من تكرار المواقف.", rule: "عند الجمود، أعد تعريف المشكلة أو جزّئها أو اطلب معياراً محايداً بدلاً من تكرار المواقف.", meaning: "الجمود التفاوضي", sentence: "Bağımsız bir ölçüt kullanarak görüşmeleri yeniden başlattık.", translation: "استأنفنا المباحثات باستخدام معيار مستقل.", form: "nesnel ölçüt", functionText: "معيار موضوعي", task: "اقترح ثلاث وسائل لكسر الجمود في حالة تفاوضية افتراضية.", example: "Sorunu yeniden çerçevelemek yeni seçenekler açabilir. | قد تفتح إعادة تأطير المشكلة خيارات جديدة.", dialogue: "A: Aynı noktada dönüp duruyoruz. — نكرر النقطة نفسها باستمرار.\\nB: Konuyu ölçülebilir ölçütlere ayıralım. — لنقسم الموضوع إلى معايير قابلة للقياس."),
    _Spec(unitId: "c2-u16", number: 576, title: "إعادة الصياغة لبناء التوافق", term: "yansıtıcı yeniden ifade", goal: "أعد صياغة كلام الطرف الآخر بصورة محايدة، ثم تحقق من دقة فهمك قبل اقتراح الحل.", rule: "أعد صياغة كلام الطرف الآخر بصورة محايدة، ثم تحقق من دقة فهمك قبل اقتراح الحل.", meaning: "إعادة الصياغة العاكسة", sentence: "Talebinizi doğru anladıysam, asıl kaygınız uygulama takvimidir.", translation: "إذا فهمت طلبكم جيداً، فإن مصدر قلقكم الأساسي هو جدول التنفيذ.", form: "anlamı doğrulama", functionText: "التحقق من المعنى", task: "حوّل ثلاث عبارات تصادمية إلى صيغ محايدة تتحقق من المعنى.", example: "Tarafsız ifade savunmacılığı azaltabilir. | قد تقلل الصياغة المحايدة النزعة الدفاعية.", dialogue: "A: Bizi hiç dinlemiyorsunuz. — أنتم لا تصغون إلينا أبداً.\\nB: Önceliklerinizin yeterince dikkate alınmadığını düşünüyorsunuz, doğru mu? — ترون أن أولوياتكم لا تؤخذ بالاعتبار بما يكفي، أهذا صحيح؟"),
    _Spec(unitId: "c2-u16", number: 577, title: "إدارة التنازلات المتبادلة", term: "karşılıklı taviz", goal: "لا تقدم تنازلاً منفرداً؛ اربطه بقيمة مقابلة، وسجل أثره على الاتفاق النهائي.", rule: "لا تقدم تنازلاً منفرداً؛ اربطه بقيمة مقابلة، وسجل أثره على الاتفاق النهائي.", meaning: "تنازل متبادل", sentence: "Her tavizi karşılıklı bir kazanımla ilişkilendirdik.", translation: "ربطنا كل تنازل بمكسب متبادل.", form: "taviz dengesi", functionText: "توازن التنازلات", task: "أنشئ جدولاً يربط كل تنازل بالمقابل والقيمة والمخاطر.", example: "Tavizlerin dengesi sürdürülebilir anlaşmayı destekler. | يدعم توازن التنازلات استدامة الاتفاق.", dialogue: "A: Bu maddeden vazgeçebiliriz. — يمكننا التخلي عن هذا البند.\\nB: Bunun karşılığında hangi güvenceyi alacağız? — ما الضمان الذي سنحصل عليه في المقابل؟"),
    _Spec(unitId: "c2-u16", number: 578, title: "صياغة بنود الاتفاق", term: "anlaşma hükmü", goal: "استخدم لغة محددة، وحدد الأطراف والأفعال والمواعيد وآلية التحقق والاستثناءات.", rule: "استخدم لغة محددة، وحدد الأطراف والأفعال والمواعيد وآلية التحقق والاستثناءات.", meaning: "بند اتفاق", sentence: "Tarafların sorumlulukları ve teslim tarihleri açıkça yazıldı.", translation: "كُتبت مسؤوليات الأطراف ومواعيد التسليم بوضوح.", form: "uygulama maddesi", functionText: "بند تنفيذي", task: "حرر بنداً اتفاقياً يتضمن مسؤولية وموعداً ومؤشر تحقق.", example: "Açık hükümler yorum farklılıklarını sınırlar. | تحد البنود الواضحة من اختلافات التفسير.", dialogue: "A: Bu ifade yeterince açık mı? — هل هذه العبارة واضحة بما يكفي؟\\nB: Sorumlu tarafı ve tarihi de belirtmeliyiz. — ينبغي أن نحدد الطرف المسؤول والتاريخ أيضاً."),
    _Spec(unitId: "c2-u16", number: 579, title: "متابعة تنفيذ الاتفاق", term: "uygulama takibi", goal: "حوّل الالتزامات إلى مؤشرات ومواعيد ومراجعات دورية، وحدد طريقة معالجة التأخر.", rule: "حوّل الالتزامات إلى مؤشرات ومواعيد ومراجعات دورية، وحدد طريقة معالجة التأخر.", meaning: "متابعة التنفيذ", sentence: "Kararların uygulanmasını ölçülebilir göstergelerle izliyoruz.", translation: "نتابع تنفيذ القرارات بمؤشرات قابلة للقياس.", form: "ilerleme göstergesi", functionText: "مؤشر التقدم", task: "صمم لوحة متابعة لاتفاق تشمل المؤشر والمسؤول والموعد والحالة.", example: "Düzenli izleme, anlaşmanın kâğıt üzerinde kalmasını önler. | تمنع المتابعة المنتظمة بقاء الاتفاق حبراً على ورق.", dialogue: "A: Uygulamayı nasıl değerlendireceğiz? — كيف سنقيّم التنفيذ؟\\nB: Aylık göstergeleri ve sapmaları inceleyeceğiz. — سنراجع المؤشرات الشهرية والانحرافات."),
    _Spec(unitId: "c2-u16", number: 580, title: "مشروع تفاوض ووساطة متكامل", term: "bütünleşik arabuluculuk", goal: "ادمج التحضير والاستماع وإعادة الصياغة وصناعة الخيارات وتحرير الاتفاق وتقييم التنفيذ.", rule: "ادمج التحضير والاستماع وإعادة الصياغة وصناعة الخيارات وتحرير الاتفاق وتقييم التنفيذ.", meaning: "وساطة متكاملة", sentence: "Arabuluculuk sürecini ortak bir uygulama planıyla tamamladık.", translation: "أنهينا عملية الوساطة بخطة تنفيذ مشتركة.", form: "uzlaşma planı", functionText: "خطة التوافق", task: "نفذ محاكاة تفاوض متعددة الأطراف وسلّم محضر اتفاق وخطة متابعة.", example: "Başarı, yalnızca anlaşmaya değil uygulanabilirliğe de bağlıdır. | لا يعتمد النجاح على الاتفاق وحده بل على قابليته للتنفيذ أيضاً.", dialogue: "A: Görüşmeleri nasıl sonuçlandıracağız? — كيف سننهي المباحثات؟\\nB: Maddeleri, sorumluları ve izleme takvimini birlikte onaylayalım. — لنعتمد البنود والمسؤولين وجدول المتابعة معاً."),
    _Spec(unitId: "c2-u17", number: 581, title: "تحليل صوت الكاتب وأسلوبه", term: "yazarın sesi", goal: "حلل اختيار المفردات والإيقاع ووجهة النظر وبناء الجمل لتحديد السمات الأسلوبية للكاتب.", rule: "حلل اختيار المفردات والإيقاع ووجهة النظر وبناء الجمل لتحديد السمات الأسلوبية للكاتب.", meaning: "صوت الكاتب", sentence: "Yazarın sesini sözcük seçimi ve cümle ritmi belirginleştiriyor.", translation: "يبرز صوت الكاتب من خلال اختيار الكلمات وإيقاع الجمل.", form: "üslup çözümlemesi", functionText: "تحليل الأسلوب", task: "حلل فقرة وحدد خمس سمات أسلوبية مدعومة بأمثلة من النص.", example: "Üslup, tek tek sözcüklerden çok seçimlerin bütününde görülür. | يظهر الأسلوب في مجموع الاختيارات لا في الكلمات المفردة فقط.", dialogue: "A: Metnin tonu neden farklı? — لماذا تختلف نبرة النص؟\\nB: Kısa cümleler ve ölçülü sözcükler anlatıcı sesini kuruyor. — تبني الجمل القصيرة والكلمات المتزنة صوت الراوي."),
    _Spec(unitId: "c2-u17", number: 582, title: "اختيار السجل اللغوي في الترجمة", term: "dil düzeyi", goal: "طابق درجة الرسمية والمسافة الاجتماعية ونبرة النص الأصلي مع سياق اللغة الهدف.", rule: "طابق درجة الرسمية والمسافة الاجتماعية ونبرة النص الأصلي مع سياق اللغة الهدف.", meaning: "السجل اللغوي", sentence: "Resmî hitabı hedef metinde de tutarlı biçimde koruduk.", translation: "حافظنا على أسلوب المخاطبة الرسمي باتساق في النص الهدف.", form: "resmiyet derecesi", functionText: "درجة الرسمية", task: "ترجم العبارة نفسها بثلاث درجات: رسمية ومحايدة وودية، واشرح الاختلاف.", example: "Dil düzeyi, konuşanlar arasındaki ilişkiyi yansıtır. | يعكس السجل اللغوي العلاقة بين المتحدثين.", dialogue: "A: Burada samimi bir ifade uygun mu? — هل تناسب هنا عبارة ودية؟\\nB: Kurumsal bağlam nedeniyle resmî dil daha doğru. — بسبب السياق المؤسسي فاللغة الرسمية أنسب."),
    _Spec(unitId: "c2-u17", number: 583, title: "ترجمة التعبيرات الاصطلاحية", term: "deyimsel ifade", goal: "انقل وظيفة التعبير الاصطلاحي وأثره، ولا تترجم مكوناته حرفياً إذا أفسد ذلك المعنى.", rule: "انقل وظيفة التعبير الاصطلاحي وأثره، ولا تترجم مكوناته حرفياً إذا أفسد ذلك المعنى.", meaning: "تعبير اصطلاحي", sentence: "Deyimi kelimesi kelimesine değil, bağlamdaki işleviyle çevirdim.", translation: "ترجمت التعبير الاصطلاحي وفق وظيفته في السياق لا حرفياً.", form: "işlevsel eşdeğer", functionText: "مكافئ وظيفي", task: "اختر خمسة تعبيرات اصطلاحية واقترح مقابلات طبيعية في العربية.", example: "İşlevsel eşdeğerlik çoğu zaman sözcüksel benzerlikten önemlidir. | غالباً ما يكون التكافؤ الوظيفي أهم من التشابه اللفظي.", dialogue: "A: Bu deyimi aynen çevirelim mi? — هل نترجم هذا التعبير كما هو؟\\nB: Önce aynı etkiyi veren doğal karşılığı arayalım. — لنبحث أولاً عن مقابل طبيعي يحقق الأثر نفسه."),
    _Spec(unitId: "c2-u17", number: 584, title: "نقل الاستعارة والصورة البلاغية", term: "metafor aktarımı", goal: "حدد الصورة البلاغية ووظيفتها، ثم قرر الحفاظ عليها أو تكييفها أو شرحها بحسب الجمهور.", rule: "حدد الصورة البلاغية ووظيفتها، ثم قرر الحفاظ عليها أو تكييفها أو شرحها بحسب الجمهور.", meaning: "نقل الاستعارة", sentence: "Metaforun çağrışımını hedef dilde korumaya çalıştım.", translation: "حاولت الحفاظ على إيحاء الاستعارة في اللغة الهدف.", form: "imge değeri", functionText: "القيمة التصويرية", task: "قارن ثلاث ترجمات لاستعارة واحدة وقيّم أثر كل منها.", example: "İmgeyi korumak anlam ve üslup dengesini gerektirir. | يتطلب الحفاظ على الصورة توازناً بين المعنى والأسلوب.", dialogue: "A: İmgeyi değiştirmek zorunda mıyız? — هل علينا تغيير الصورة البلاغية؟\\nB: Hedef okurda aynı işlevi görüyorsa uyarlayabiliriz. — يمكننا تكييفها إذا أدت الوظيفة نفسها لدى القارئ المستهدف."),
    _Spec(unitId: "c2-u17", number: 585, title: "إيقاع الجملة وبنيتها", term: "cümle ritmi", goal: "وازن طول الجمل وترتيبها والوقفات بما يحافظ على إيقاع النص ووظيفته.", rule: "وازن طول الجمل وترتيبها والوقفات بما يحافظ على إيقاع النص ووظيفته.", meaning: "إيقاع الجملة", sentence: "Uzun ve kısa cümleleri dengeleyerek anlatımın ritmini korudum.", translation: "حافظت على إيقاع السرد بموازنة الجمل الطويلة والقصيرة.", form: "sözdizimsel ritim", functionText: "الإيقاع التركيبي", task: "أعد كتابة فقرة مع الحفاظ على الإيقاع والتأثير لا ترتيب الكلمات فقط.", example: "Sözdizimi, metnin temposunu ve vurgusunu etkiler. | يؤثر التركيب في سرعة النص ومواضع توكيده.", dialogue: "A: Cümleyi neden böldün? — لماذا قسمت الجملة؟\\nB: Vurguyu ve okuma temposunu daha doğal kılmak için. — لجعل التوكيد وإيقاع القراءة أكثر طبيعية."),
    _Spec(unitId: "c2-u17", number: 586, title: "إدارة الغموض المقصود", term: "anlam belirsizliği", goal: "ميّز الغموض الفني المقصود عن الالتباس غير المرغوب، وحافظ على تعدد المعنى حين يكون جزءاً من الأثر.", rule: "ميّز الغموض الفني المقصود عن الالتباس غير المرغوب، وحافظ على تعدد المعنى حين يكون جزءاً من الأثر.", meaning: "الغموض الدلالي", sentence: "Metindeki bilinçli belirsizliği çeviride koruduk.", translation: "حافظنا في الترجمة على الغموض المقصود في النص.", form: "çok anlamlılık", functionText: "تعدد المعاني", task: "حلل موضعين غامضين وقرر ما ينبغي الحفاظ عليه وما ينبغي توضيحه.", example: "Her belirsizlik hata değildir; bazıları estetik işlev taşır. | ليس كل غموض خطأ؛ فبعضه يؤدي وظيفة جمالية.", dialogue: "A: Bu cümleyi açıklığa kavuşturalım mı? — هل نوضح هذه الجملة؟\\nB: Önce belirsizliğin bilinçli olup olmadığını belirleyelim. — لنحدد أولاً إن كان الغموض مقصوداً."),
    _Spec(unitId: "c2-u17", number: 587, title: "نقل الإحالات الثقافية", term: "kültürel gönderme", goal: "حدد المرجع الثقافي ومعرفة الجمهور به، ثم اختر الإبقاء أو التوضيح أو التكييف دون محو دلالته.", rule: "حدد المرجع الثقافي ومعرفة الجمهور به، ثم اختر الإبقاء أو التوضيح أو التكييف دون محو دلالته.", meaning: "إحالة ثقافية", sentence: "Kültürel göndermeyi kısa bir açıklamayla anlaşılır kıldım.", translation: "جعلت الإحالة الثقافية مفهومة بشرح موجز.", form: "kültürel bağlam", functionText: "السياق الثقافي", task: "اختر إحالات من نص أدبي وحدد استراتيجية مناسبة لنقلها.", example: "Kültürel bağlam, göndermenin yorumunu belirler. | يحدد السياق الثقافي طريقة فهم الإحالة.", dialogue: "A: Okur bu göndermeyi tanımayabilir. — قد لا يعرف القارئ هذه الإحالة.\\nB: Kısa bir açıklama anlamı koruyabilir. — قد يحافظ شرح قصير على المعنى."),
    _Spec(unitId: "c2-u17", number: 588, title: "ترجمة الحوار والشخصيات", term: "karakter sesi", goal: "حافظ على اختلاف أصوات الشخصيات وإيقاع التبادل وسمات الحديث بما يخدم بناء الشخصية.", rule: "حافظ على اختلاف أصوات الشخصيات وإيقاع التبادل وسمات الحديث بما يخدم بناء الشخصية.", meaning: "صوت الشخصية", sentence: "Her karakterin konuşma biçimini ayrı ayrı korudum.", translation: "حافظت على طريقة حديث كل شخصية بصورة مستقلة.", form: "konuşma doğallığı", functionText: "طبيعية الحوار", task: "ترجم حواراً بين ثلاث شخصيات مع إبراز اختلاف أصواتها.", example: "Diyalog, karakteri yalnızca içerikle değil söyleyişle de kurar. | يبني الحوار الشخصية بالمضمون وطريقة القول معاً.", dialogue: "A: Üç karakter aynı şekilde mi konuşmalı? — هل ينبغي أن تتحدث الشخصيات الثلاث بالطريقة نفسها؟\\nB: Hayır, sözcük seçimi ve ritimleri farklı olmalı. — لا، يجب أن يختلف اختيار الكلمات والإيقاع."),
    _Spec(unitId: "c2-u17", number: 589, title: "مراجعة الترجمة الأدبية", term: "edebî redaksiyon", goal: "راجع الدقة والصوت والإيقاع والاتساق، ثم اقرأ النص الهدف مستقلاً لاكتشاف الصياغات المتكلفة.", rule: "راجع الدقة والصوت والإيقاع والاتساق، ثم اقرأ النص الهدف مستقلاً لاكتشاف الصياغات المتكلفة.", meaning: "تحرير أدبي", sentence: "Son okumada anlamı ve anlatım akışını birlikte değerlendirdim.", translation: "في القراءة النهائية قيّمت المعنى وانسياب التعبير معاً.", form: "son okuma", functionText: "القراءة النهائية", task: "حرر ترجمة قصيرة عبر جولات منفصلة للدقة والأسلوب والإيقاع.", example: "İyi redaksiyon, görünür hataları düzeltirken metnin sesini korur. | يصحح التحرير الجيد الأخطاء مع الحفاظ على صوت النص.", dialogue: "A: Yalnızca yazım hatalarını mı arayalım? — هل نبحث عن الأخطاء الإملائية فقط؟\\nB: Akıcılığı ve anlatıcı sesini de inceleyelim. — لنراجع الانسياب وصوت الراوي أيضاً."),
    _Spec(unitId: "c2-u17", number: 590, title: "ملف إنجاز الترجمة الأدبية", term: "çeviri portfolyosu", goal: "اجمع النص الأصلي والترجمة والمسودات والقرارات التحريرية وتعليقات المراجعة في ملف موثق.", rule: "اجمع النص الأصلي والترجمة والمسودات والقرارات التحريرية وتعليقات المراجعة في ملف موثق.", meaning: "ملف إنجاز الترجمة", sentence: "Çeviri kararlarımı örneklerle açıklayan bir portfolyo hazırladım.", translation: "أعددت ملف إنجاز يشرح قراراتي الترجمية بالأمثلة.", form: "çeviri notu", functionText: "ملاحظة ترجمية", task: "أنشئ ملفاً يضم ترجمة أدبية وتعليقات تشرح أهم القرارات.", example: "Portfolyo, yalnızca sonucu değil karar sürecini de gösterir. | يعرض ملف الإنجاز عملية اتخاذ القرار لا النتيجة وحدها.", dialogue: "A: Portfolyoda hangi belgeler bulunmalı? — ما الوثائق التي ينبغي أن يتضمنها الملف؟\\nB: Kaynak metin, taslaklar ve gerekçeli kararlar. — النص الأصلي والمسودات والقرارات المبررة."),
    _Spec(unitId: "c2-u18", number: 591, title: "التحقق المتقاطع من المصادر", term: "çapraz doğrulama", goal: "قارن الادعاء بين مصادر مستقلة، وافحص أصل البيانات وتاريخها ومصالح الجهة الناشرة.", rule: "قارن الادعاء بين مصادر مستقلة، وافحص أصل البيانات وتاريخها ومصالح الجهة الناشرة.", meaning: "التحقق المتقاطع", sentence: "İddiayı birbirinden bağımsız üç kaynakla doğruladık.", translation: "تحققنا من الادعاء بثلاثة مصادر مستقلة عن بعضها.", form: "kaynak güvenilirliği", functionText: "موثوقية المصدر", task: "افحص ادعاءً عاماً وحدد مصادر مستقلة تؤيده أو تنقضه.", example: "Kaynak sayısından çok bağımsızlık ve yöntem önemlidir. | الاستقلالية والمنهج أهم من عدد المصادر.", dialogue: "A: Birden fazla site aynı haberi veriyor. — عدة مواقع تنشر الخبر نفسه.\\nB: Kaynakların bağımsız olup olmadığını kontrol edelim. — لنتحقق مما إذا كانت المصادر مستقلة."),
    _Spec(unitId: "c2-u18", number: 592, title: "تفسير الادعاءات الإحصائية", term: "istatistiksel iddia", goal: "افحص حجم العينة والمقام والفترة الزمنية وطريقة القياس قبل قبول المقارنة الإحصائية.", rule: "افحص حجم العينة والمقام والفترة الزمنية وطريقة القياس قبل قبول المقارنة الإحصائية.", meaning: "ادعاء إحصائي", sentence: "Oranları karşılaştırmadan önce örneklem büyüklüklerini inceledik.", translation: "فحصنا أحجام العينات قبل مقارنة النسب.", form: "payda", functionText: "المقام الإحصائي", task: "حلل خبراً يتضمن نسبة مئوية وحدد المعلومات اللازمة لفهمها.", example: "Payda bilinmeden oran yanıltıcı olabilir. | قد تكون النسبة مضللة دون معرفة مقامها.", dialogue: "A: Oran yüzde elli artmış. — ارتفعت النسبة خمسين بالمئة.\\nB: Başlangıç değerini ve ölçüm dönemini de bilmeliyiz. — يجب أن نعرف القيمة الأولية وفترة القياس أيضاً."),
    _Spec(unitId: "c2-u18", number: 593, title: "التعبير عن عدم اليقين", term: "belirsizlik payı", goal: "استخدم درجات اليقين بدقة، وافصل ما تثبته البيانات عما ترجحه أو لا تسمح بتحديده.", rule: "استخدم درجات اليقين بدقة، وافصل ما تثبته البيانات عما ترجحه أو لا تسمح بتحديده.", meaning: "هامش عدم اليقين", sentence: "Verilerin kesin sonuç vermediğini açıkça belirttik.", translation: "أوضحنا أن البيانات لا تقدم نتيجة قطعية.", form: "olasılık dili", functionText: "لغة الاحتمال", task: "أعد صياغة خمس نتائج لتفصل المؤكد والمرجح وغير المحسوم.", example: "Belirsizliği belirtmek, bulguyu zayıflatmaz; doğru sınırlar. | لا يضعف توضيح عدم اليقين النتيجة بل يحدد حدودها بدقة.", dialogue: "A: Bu sonuç kesin mi? — هل هذه النتيجة مؤكدة؟\\nB: Mevcut veriler yalnızca güçlü bir olasılığı destekliyor. — البيانات الحالية تدعم احتمالاً قوياً فقط."),
    _Spec(unitId: "c2-u18", number: 594, title: "تحليل تأطير المعلومات المضللة", term: "yanıltıcı çerçeve", goal: "افحص الانتقاء والحذف والعنوان والسياق والصور لمعرفة كيف يتغير انطباع المتلقي.", rule: "افحص الانتقاء والحذف والعنوان والسياق والصور لمعرفة كيف يتغير انطباع المتلقي.", meaning: "تأطير مضلل", sentence: "Başlık, verinin yalnızca bir bölümünü öne çıkarıyordu.", translation: "كان العنوان يبرز جزءاً واحداً فقط من البيانات.", form: "bağlamdan koparma", functionText: "اقتطاع السياق", task: "قارن العنوان بالمادة الكاملة وحدد ما حُذف أو ضُخم.", example: "Çerçeveleme, doğru bilgiyi bile yanıltıcı sunabilir. | قد يجعل التأطير المعلومة الصحيحة مضللة في عرضها.", dialogue: "A: Başlık verilerle çelişiyor mu? — هل يتعارض العنوان مع البيانات؟\\nB: Tam olarak değil; ancak önemli bağlamı dışarıda bırakıyor. — ليس تماماً، لكنه يستبعد سياقاً مهماً."),
    _Spec(unitId: "c2-u18", number: 595, title: "تحليل صياغة العناوين الصحفية", term: "haber çerçevesi", goal: "حلل الأفعال والتوصيفات والأرقام والفاعل المحذوف لمعرفة موقف العنوان وتأثيره.", rule: "حلل الأفعال والتوصيفات والأرقام والفاعل المحذوف لمعرفة موقف العنوان وتأثيره.", meaning: "إطار الخبر", sentence: "Başlığın seçtiği fiil, olayın algılanışını değiştirdi.", translation: "غيّر الفعل الذي اختاره العنوان طريقة إدراك الحدث.", form: "başlık dili", functionText: "لغة العنوان", task: "اكتب عنوانين محايداً وآخر منحازاً للواقعة نفسها ثم قارن أثرهما.", example: "Başlık, okurun ilk yorumunu güçlü biçimde etkiler. | يؤثر العنوان بقوة في التفسير الأولي للقارئ.", dialogue: "A: Bu başlık tarafsız mı? — هل هذا العنوان محايد؟\\nB: Seçilen sıfat değerlendirme içeriyor; yeniden yazalım. — الصفة المختارة تحمل حكماً؛ لنعِد صياغته."),
    _Spec(unitId: "c2-u18", number: 596, title: "إجراء مقابلة متعمقة", term: "açık uçlu soru", goal: "ابن أسئلة مفتوحة ومحايدة، واطلب أمثلة، وتابع الإجابات دون تلقين المشارك رأياً.", rule: "ابن أسئلة مفتوحة ومحايدة، واطلب أمثلة، وتابع الإجابات دون تلقين المشارك رأياً.", meaning: "سؤال مفتوح", sentence: "Katılımcının deneyimini anlamak için açık uçlu sorular kullandım.", translation: "استخدمت أسئلة مفتوحة لفهم تجربة المشارك.", form: "takip sorusu", functionText: "سؤال متابعة", task: "صمم دليلاً لمقابلة يتضمن أسئلة رئيسية وأسئلة متابعة محايدة.", example: "İyi soru, yanıtı yönlendirmeden ayrıntıyı ortaya çıkarır. | يكشف السؤال الجيد التفاصيل دون توجيه الإجابة.", dialogue: "A: Neden böyle düşündünüz? — لماذا فكرت بهذه الطريقة؟\\nB: Bu kararı etkileyen deneyimi anlatabilir misiniz? — هل يمكنك وصف التجربة التي أثرت في هذا القرار؟"),
    _Spec(unitId: "c2-u18", number: 597, title: "كتابة موجز سياساتي", term: "politika notu", goal: "لخص المشكلة والأدلة والخيارات والتبعات والتوصية في وثيقة قصيرة موجهة لصانع القرار.", rule: "لخص المشكلة والأدلة والخيارات والتبعات والتوصية في وثيقة قصيرة موجهة لصانع القرار.", meaning: "موجز سياساتي", sentence: "Notta seçenekleri ve olası etkileri karşılaştırdık.", translation: "قارنّا الخيارات وآثارها المحتملة في الموجز.", form: "politika önerisi", functionText: "توصية سياساتية", task: "اكتب موجزاً من صفحة واحدة يوازن بين ثلاثة خيارات وتبعاتها.", example: "Politika notu, karar vermeyi kolaylaştıran seçici bir belgedir. | الموجز السياساتي وثيقة انتقائية تسهل اتخاذ القرار.", dialogue: "A: Bütün ayrıntıları ekleyelim mi? — هل نضيف جميع التفاصيل؟\\nB: Kararı etkileyen kanıtları ve seçenekleri seçelim. — لنختر الأدلة والخيارات التي تؤثر في القرار."),
    _Spec(unitId: "c2-u18", number: 598, title: "التواصل العام المبني على الأدلة", term: "kanıta dayalı iletişim", goal: "قدم الأدلة بلغة مفهومة، واذكر القيود، وافصل التفسير عن الرأي، وصحح المعلومات بشفافية.", rule: "قدم الأدلة بلغة مفهومة، واذكر القيود، وافصل التفسير عن الرأي، وصحح المعلومات بشفافية.", meaning: "تواصل قائم على الأدلة", sentence: "Kamuya açık açıklamada bulguları ve sınırlılıkları birlikte sunduk.", translation: "عرضنا النتائج والقيود معاً في البيان العام.", form: "şeffaf açıklama", functionText: "توضيح شفاف", task: "اكتب بياناً عاماً يشرح نتيجة مع حدودها وما لا يمكن استنتاجه منها.", example: "Şeffaflık, güvenilir iletişimin temelidir. | الشفافية أساس التواصل الموثوق.", dialogue: "A: Sınırlılıkları belirtmek güveni azaltır mı? — هل يقلل ذكر القيود الثقة؟\\nB: Aksine, değerlendirmeyi daha güvenilir kılar. — على العكس، يجعل التقييم أكثر موثوقية."),
